window.CubeApiDocs.define("api-Data_Management-申请对话频道",{"id":"api-Data_Management-申请对话频道","versions":[{"version":"1.0.0","toc":[{"id":"overview","title":"用途与调用说明"},{"id":"request-example","title":"请求示例"},{"id":"parameters","title":"路径与通用参数"},{"id":"body","title":"请求体参数"},{"id":"success","title":"成功响应"},{"id":"errors","title":"错误与处理"}],"html":"\u003carticle data-api-id=\"api-Data_Management-申请对话频道\">\u003cheader class=\"article-header\">\u003cp class=\"eyebrow\">数据管理 · v1.0.0\u003c/p>\u003ch1 tabindex=\"-1\">申请对话频道\u003c/h1>\u003cdiv class=\"endpoint\">\u003cspan class=\"method post\">POST\u003c/span>\u003ccode>/aigc/channel/:token\u003c/code>\u003cbutton type=\"button\" data-copy=\"path\" aria-label=\"复制接口路径\">复制路径\u003c/button>\u003c/div>\u003c/header>\u003csection class=\"doc-section\" id=\"overview\">\u003ch2>用途与调用说明\u003c/h2>\u003cp>申请对话频道。每个对话频道对应一组独立的对话模型，对话内容仅在该频道内的模型进行处理。 \u003cp>频道的空闲超时时间为30分钟，30分钟内无对话频道将自动销毁。\u003c/p>\u003c/p>\u003c/section>\u003csection class=\"doc-section\" id=\"request-example\">\u003ch2>请求示例\u003c/h2>\u003cdiv class=\"example\">\u003ch3>请求示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"participant\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"来自火星的星星\"\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"parameters\">\u003ch2>路径与通用参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Parameter\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>token\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>授权令牌。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"body\">\u003ch2>请求体参数\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"字段说明\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型 / 要求\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>participant\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement \">必填\u003c/span>\u003c/td>\u003ctd>\u003cp>对话参与人名称。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>unit\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003cspan class=\"requirement optional\">可选\u003c/span>\u003c/td>\u003ctd>\u003cp>指定该频道使用的大模型单元。默认值：\u003ccode>Baize\u003c/code>。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"success\">\u003ch2>成功响应\u003c/h2>\u003cdiv class=\"example\">\u003ch3>应答示例\u003c/h3>\u003cdiv class=\"code-block\">\u003cdiv class=\"code-toolbar\">\u003cspan>json\u003c/span>\u003cbutton type=\"button\" data-copy=\"code\">复制代码\u003c/button>\u003c/div>\u003cpre tabindex=\"0\">\u003ccode>HTTP/\u003cspan class=\"token number\">1.1\u003c/span> \u003cspan class=\"token number\">200\u003c/span> OK\n\u003cspan class=\"token punctuation\">{\u003c/span>\n    \u003cspan class=\"token property\">\"code\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"KLKVaPXDZCPRjMPx\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"creationTime\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token number\">1680139631664\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"participant\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"来自火星的星星\"\u003c/span>\u003cspan class=\"token punctuation\">,\u003c/span>\n    \u003cspan class=\"token property\">\"language\"\u003c/span>\u003cspan class=\"token operator\">:\u003c/span> \u003cspan class=\"token string\">\"cn\"\u003c/span>\n\u003cspan class=\"token punctuation\">}\u003c/span>\u003c/code>\u003c/pre>\u003c/div>\u003c/div>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Success 200\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>code\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>频道代码。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>creationTime\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Number\u003c/code>\u003c/td>\u003ctd>\u003cp>创建时间戳。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>participant\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>参与人名称。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>language\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">String\u003c/code>\u003c/td>\u003ctd>\u003cp>频道使用的语言标识：\u003ccode>cn\u003c/code> 中文、\u003ccode>en\u003c/code> 英文。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>authToken\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">Object\u003c/code>\u003c/td>\u003ctd>\u003cp>频道关联的鉴权令牌数据，仅在该频道带令牌时返回。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003csection class=\"doc-section\" id=\"errors\">\u003ch2>错误与处理\u003c/h2>\u003cdiv class=\"table-scroll\" tabindex=\"0\" role=\"region\" aria-label=\"Error 4xx\">\u003ctable>\u003cthead>\u003ctr>\u003cth>字段\u003c/th>\u003cth>类型\u003c/th>\u003cth>说明\u003c/th>\u003c/tr>\u003c/thead>\u003ctbody>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>400\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>服务节点访问错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>401\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>Token 无效。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>403\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>404\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>必填参数错误。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003cth scope=\"row\" style=\"--depth:0\">\u003ccode>406\u003c/code>\u003c/th>\u003ctd>\u003ccode class=\"field-type\">—\u003c/code>\u003c/td>\u003ctd>\u003cp>请求过于频繁，被限流。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003c/div>\u003c/section>\u003c/article>"}]});
